// Extract jobs from webhook payload
const payload = $input.first().json;
const jobs = payload.jobs || payload.data || (Array.isArray(payload) ? payload : [payload]);

// Configuration
const priorityLocations = ['san diego', 'langley', 'norfolk', 'dayton', 'huntsville', 'colorado springs', 'tampa', 'washington', 'arlington', 'mclean', 'reston'];
const priorityClearances = ['ts/sci', 'top secret/sci', 'top secret', 'ts'];

// Return each job as separate item
return jobs.map(job => ({
    json: {
        ...job,
        _config: { priorityLocations, priorityClearances }
    }
}));

// Filter for high-priority jobs
const jobs = $input.all();
const config = jobs[0]?.json._config || { priorityLocations: [], priorityClearances: [] };

const highPriority = jobs.filter(item => {
    const job = item.json;
    const clearance = (job.detected_clearance || job.clearance || '').toLowerCase();
    const location = (job.location || '').toLowerCase();

    // Check clearance match
    const hasHighClearance = config.priorityClearances.some(c => clearance.includes(c));

    // Check location match
    const isKeyLocation = config.priorityLocations.some(loc => location.includes(loc));

    // High priority if high clearance in key location
    // OR if very high clearance (TS/SCI) anywhere
    const isVeryHighClearance = clearance.includes('ts/sci') || clearance.includes('sci');

    return (hasHighClearance && isKeyLocation) || isVeryHighClearance;
});

if (highPriority.length === 0) {
    // Return empty marker
    return [{
        json: {
            _empty: true,
            total_processed: jobs.length,
            message: "No high-priority jobs in this batch"
        }
    }];
}

// Return high-priority jobs (without config)
return highPriority.map(item => {
    const { _config, ...job } = item.json;
    return { json: job };
});

// Get job data from the filter step
const job = $('Filter High Priority').first().json;

// Get context data
const programContext = $('Get Program Context').first()?.json || {};
const relatedContacts = $('Get Related Contacts').first()?.json?.contacts || [];

// Priority level based on clearance
const clearance = (job.detected_clearance || '').toLowerCase();
let priorityEmoji = '📋';
let priorityLevel = 'Standard';
if (clearance.includes('ts/sci')) {
    priorityEmoji = '🔴';
    priorityLevel = 'Critical';
} else if (clearance.includes('top secret')) {
    priorityEmoji = '🟠';
    priorityLevel = 'High';
} else if (clearance.includes('secret')) {
    priorityEmoji = '🟡';
    priorityLevel = 'Medium';
}

// Format related programs
const relatedPrograms = (programContext.results || [])
    .slice(0, 3)
    .map(p => p.name || p.title || 'Unknown Program');

// Format contacts
const contactList = relatedContacts
    .slice(0, 3)
    .map(c => `${c.name} (${c.title || 'Unknown'})`)
    .join(', ');

// Build the alert
const alert = {
    priority_level: priorityLevel,
    priority_emoji: priorityEmoji,

    job: {
        title: job.title,
        company: job.company,
        location: job.location,
        clearance: job.detected_clearance || 'Not specified',
        url: job.url,
        posted_date: job.posted_date || job.date_posted
    },

    context: {
        related_programs: relatedPrograms,
        related_contacts: contactList || 'No known contacts',
        program_count: relatedPrograms.length,
        contact_count: relatedContacts.length
    },

    alert_time: new Date().toISOString()
};

// Build Slack message
const message = `${priorityEmoji} *${priorityLevel.toUpperCase()} PRIORITY JOB ALERT* ${priorityEmoji}

*${alert.job.title}*
🏢 ${alert.job.company}
📍 ${alert.job.location}
🔒 ${alert.job.clearance}
${alert.job.posted_date ? `📅 Posted: ${alert.job.posted_date}` : ''}

*Related Context:*
${relatedPrograms.length > 0 ? `• Programs: ${relatedPrograms.join(', ')}` : '• No related programs found'}
${relatedContacts.length > 0 ? `• Contacts: ${contactList}` : '• No known contacts'}

🔗 ${alert.job.url || 'URL not available'}`;

return [{
    json: {
        message,
        alert
    }
}];

return [{
    json: {
        status: "skipped",
        reason: "No high-priority jobs in batch",
        timestamp: new Date().toISOString()
    }
}];
